// Generates TypeScript types from the JSON Schemas in ../schema so the app and the
// Python pipeline share one definition. Run: pnpm gen:types
import { compileFromFile } from 'json-schema-to-typescript';
import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const schemaDir = resolve(here, '../../schema');
const outFile = resolve(here, '../src/lib/types/score.generated.ts');

const banner = `/* eslint-disable */
// GENERATED by scripts/gen-types.mjs from /schema/*.json. Do not edit by hand.
`;

const parts = [];
for (const name of ['notes.v1.json', 'pieces.v1.json', 'events.v1.json']) {
	const ts = await compileFromFile(resolve(schemaDir, name), {
		bannerComment: '',
		additionalProperties: false,
		style: { singleQuote: true, useTabs: true }
	});
	parts.push(`// ---- ${name} ----\n${ts}`);
}

await mkdir(dirname(outFile), { recursive: true });
// Each schema repeats shared names only if they share $defs names, so merge by de-duplicating
// identical top-level declarations.
const seen = new Set();
const merged = parts
	.join('\n')
	.split(/\n(?=export (?:interface|type) )/)
	.filter((block) => {
		const m = block.match(/^export (?:interface|type) (\w+)/);
		if (!m) return true;
		if (seen.has(m[1])) return false;
		seen.add(m[1]);
		return true;
	})
	.join('\n');
await writeFile(outFile, banner + merged);
console.log('wrote', outFile);
